#[tokio::test]
async fn group_completion_gate_fails_closed_when_worktree_is_missing() {
    // 写入范围门禁无法读取 completion commit 的 git 事实时，必须失败关闭；
    // 返回空 changed_files 会让 exclusive scope 校验零次迭代并静默放行。
    let (_root, _paths, _store, engine, attempt) =
        group_attempt_with_committed_unit_changes("web/src/app.tsx", "web/src/app.tsx", &[]);
    let worktree = attempt
        .worktree_path
        .as_ref()
        .expect("group attempt worktree path");
    fs::remove_dir_all(worktree).expect("remove worktree to simulate missing git facts");

    let error = engine
        .handle_final_confirm(&attempt.project_id, &attempt.issue_id, &attempt.id)
        .await
        .expect_err("missing worktree must fail the group completion gate closed");

    assert!(
        matches!(
            error,
            cadence_aria::product::coding_workspace_engine::CodingWorkspaceEngineError::MissingWorktree(ref attempt_id)
                if attempt_id == &attempt.id
        ),
        "缺少 git 事实时必须报告 MissingWorktree，实际: {error:?}"
    );
}
    let attempt = store
        .update_attempt_head_commit(
            &attempt.project_id,
            &attempt.issue_id,
            &attempt.id,
            Some("deadbeef".to_string()),
        )
        .expect("set head commit");
    lifecycle
        .upsert_issue_shared_worktree(UpsertIssueSharedWorktreeInput {
            project_id: "project_0001".to_string(),
            issue_id: "issue_0001".to_string(),
            repository_id: "repository_0001".to_string(),
            branch_name: "aria/issues/issue_0001".to_string(),
            worktree_path: paths.root().join("shared-worktree"),
            base_branch: "HEAD".to_string(),
        })
        .expect("upsert shared worktree");
    lifecycle
        .try_acquire_issue_worktree_lock(
            "project_0001",
            "issue_0001",
            "work_item_0002",
            &attempt.id,
        )
        .expect("acquire shared worktree lock");
    store
        .save_timeline_node(&attempt, CodingTimelineNode {
            id: "coding_node_0001".to_string(),
            attempt_id: attempt.id.clone(),
            stage: CodingExecutionStage::FinalConfirm,
            title: "最终确认".to_string(),
            status: CodingTimelineNodeStatus::Running,
            agent_role: Some(CodingAgentRole::System),
            summary: None,
            started_at: "2026-06-27T00:00:00Z".to_string(),
            completed_at: None,
            artifact_refs: Vec::new(),
        })
        .expect("save final confirm node");
    assert!(matches!(
        store.get_plan_binding(&attempt),
        Err(cadence_aria::product::json_store::ProductStoreError::NotFound {
            kind: "coding_attempt_plan_binding",
            ..
        })
    ));

    let error = engine
        .handle_final_confirm(&attempt.project_id, &attempt.issue_id, &attempt.id)
        .await
        .expect_err("legacy group without authoritative binding must fail closed");
    assert!(
        error.to_string().contains("coding_attempt_plan_binding"),
        "unexpected failure-closed error: {error}"
    );

    let persisted = store
        .get_attempt(&attempt.project_id, &attempt.issue_id, &attempt.id)
        .expect("persisted attempt");
    assert_eq!(persisted.status, CodingAttemptStatus::WaitingForHuman);
    assert!(persisted.completed_at.is_none());
}

